# المهمة الملف الجهد 13 إضافة JWT auth لـ copilot-api <code>copilot-api/src/api/deps.py</code> 4h 14 تنفيذ NATS event publishing <code>copilot-api/src/events/</code> 4h 15 إضافة prompt injection detection <code>copilot-api/src/core/guardrails.py</code> 4h 16 إضافة rate limiting per-user <code>copilot-api/src/main.py</code> 2h <p>التنفيذ - JWT auth:</p> <pre><code># copilot-api/src/api/deps.py
from fastapi import Depends, HTTPException, status
from fastapi.security import HTTPBearer, HTTPAuthorizationCredentials
from shared.auth.dependencies import verify_jwt_token

security = HTTPBearer()

async def get_current_user(
    credentials: HTTPAuthorizationCredentials = Depends(security)
) -&gt; dict:
    try:
        return verify_jwt_token(credentials.credentials)
    except Exception:
        raise HTTPException(
            status_code=status.HTTP_401_UNAUTHORIZED,
            detail={"error": "Invalid token", "error_ar": "رمز غير صالح"}
        )
</code></pre> <p>التنفيذ - NATS Events:</p> <pre><code># copilot-api/src/events/publisher.py
COPILOT_EVENTS = {
    "chat_started":   "sahool.copilot.chat_started",
    "chat_completed": "sahool.copilot.chat_completed",
    "tool_executed":  "sahool.copilot.tool_executed",
    "tool_blocked":   "sahool.copilot.tool_blocked",
}

async def publish_copilot_event(nc, event_type: str, data: dict):
