</code></pre> <p>التنفيذ - Prompt Injection Detection:</p> <pre><code># copilot-api/src/core/prompt_guard.py
INJECTION_PATTERNS = [
    r"ignore\s+(previous|all|above)\s+instructions",
    r"تجاهل\s+(التعليمات|الأوامر)\s+السابقة",
    r"you\s+are\s+now\s+(?:a|an)",
    r"system\s*:\s*",
    r"&lt;\|im_start\|&gt;",
    r"ADMIN_OVERRIDE",
]

def detect_prompt_injection(text: str) -&gt; bool:
    for pattern in INJECTION_PATTERNS:
        if re.search(pattern, text, re.IGNORECASE):
            return True
    return False
</code></pre>

# المهمة التفصيل الجهد 18 إضافة مصادقة WebSocket ws-gateway JWT verification 2d 19 تنفيذ Content Security Policy Next.js middleware 1d 20 إضافة server-side auth middleware apps/web/, apps/admin/ 2d 21 تنفيذ input sanitization shared/middleware/ 1d 22 إضافة httpOnly flag للـ cookies auth module 4h <p>التنفيذ:</p> <pre><code># ws-gateway JWT verification
from shared.auth.dependencies import verify_jwt_token

async def websocket_auth(websocket: WebSocket):
    token = websocket.query_params.get("token")
    if not token:
        await websocket.close(code=4001, reason="Authentication required")
        return None
    try:
        payload = verify_jwt_token(token)
        return payload
    except Exception:
        await websocket.close(code=4003, reason="Invalid token")
        return None
</code></pre> <pre><code>// Next.js CSP middleware
// apps/web/src/middleware.ts
import { NextResponse } from 'next/server';

export function middleware(request: Request) {
  const response = NextResponse.next();
  response.headers.set(
    'Content-Security-Policy',
    "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; connect-src 'self' wss://*.sahool.app https://*.sahool.app;"
  );
  return response;
}
</code></pre>

